	private DropTables()
	{
	}

	private static void table(String source, String... items)
	{
		TABLES.put(normalize(source), new ArrayList<>(Arrays.asList(items)));
	}

	private static void addDrop(String item, String... sources)
	{
		for (String source : sources)
		{
			TABLES.computeIfAbsent(normalize(source), k -> new ArrayList<>()).add(item);
		}
	}

	/** Drops that are always worth celebrating on their own (everything the Sire has comes from the Unsired). */
	static boolean isAlwaysCelebrated(String item)
	{
		return normalize(item).equals("unsired");
	}

	/** Clue scrolls and their containers never count as collection log chases. */
	static boolean isClueItem(String item)
	{
		String n = normalize(item);
		return n.startsWith("clue ") || n.startsWith("scroll box") || n.startsWith("challenge scroll")
			|| n.startsWith("reward casket");
	}

	/** Items that mean a treasure trail is underway (not bottles/nests/geodes, which are unopened). */
	static boolean isTrailItem(String item)
	{
		String n = normalize(item);
		return n.startsWith("clue scroll") || n.startsWith("challenge scroll") || n.startsWith("reward casket")
			|| n.startsWith("scroll box") || n.startsWith("puzzle box") || n.startsWith("light box");
	}

	private static void petFirst(String source, String... items)
	{
		table(source, items);
		PET_FIRST.add(normalize(source));
	}

	static boolean isPetFirst(String source)
	{
		return PET_FIRST.contains(normalize(source));
	}

	static boolean isPet(String item)
	{
		return PETS.contains(normalize(item));
	}

	/** The pet in a drop table, if any - regardless of whether it's already been obtained. */
	static String findPet(List<String> table)
	{
		for (String item : table)
		{
			if (isPet(item))
			{
				return item;
			}
		}
		return null;
	}

	private static void alias(String source, String... aliases)
	{
		for (String a : aliases)
		{
			ALIASES.put(normalize(a), source);
		}
	}

	/** Maps aliases and raid sub-boss names to their market name; anything else passes through. */
	static String canonicalSource(String name)
	{
		String canonical = ALIASES.get(normalize(name));
		return canonical != null ? canonical : name.trim();
	}

	/**
	 * True once {@code rawName} is the actual completion event for {@code canonicalSource} — the raid's own
	 * reward chest, or a non-raid source that doesn't alias away from its own name. False for a raid's
	 * room/sub-boss kills, which only alias to the raid for market display, not for counting a completion.
	 */
	static boolean isCompletion(String canonicalSource, String rawName)
	{
		return !RAIDS.contains(canonicalSource) || normalize(canonicalSource).equals(normalize(rawName));
	}

	/** Common OSRS Wiki short names, for the compact layouts. */
	private static final Map<String, String> ABBREVIATIONS = new HashMap<>();

	static
	{
		String[][] pairs = {
			{CHAMBERS_OF_XERIC, "CoX"}, {THEATRE_OF_BLOOD, "ToB"}, {TOMBS_OF_AMASCUT, "ToA"},
			{GUARDIANS_OF_THE_RIFT, "GotR"}, {THE_GAUNTLET, "Gauntlet"}, {CORRUPTED_GAUNTLET, "CG"},
			{"The Nightmare", "Nightmare"}, {"Phosani's Nightmare", "Phosani"}, {"General Graardor", "Graardor"},
			{"Kree'arra", "Kree"}, {"Commander Zilyana", "Zilyana"}, {"K'ril Tsutsaroth", "K'ril"},
			{"Corporeal Beast", "Corp"}, {"Alchemical Hydra", "Hydra"}, {"Thermonuclear smoke devil", "Thermy"},
			{"Abyssal Sire", "Sire"}, {"Grotesque Guardians", "Gargs"}, {"Kalphite Queen", "KQ"},
			{"King Black Dragon", "KBD"}, {"Dagannoth Rex", "Rex"}, {"Dagannoth Prime", "Prime"},
			{"Dagannoth Supreme", "Supreme"}, {"Giant Mole", "Mole"}, {"Phantom Muspah", "Muspah"},
			{"Chaos Elemental", "Chaos Ele"}, {"Duke Sucellus", "Duke"}, {"The Leviathan", "Leviathan"},
			{"The Whisperer", "Whisperer"}, {"The Hueycoatl", "Huey"}, {"Doom of Mokhaiotl", "Doom"},
			{"Fortis Colosseum", "Colosseum"}, {"Moons of Peril", "Moons"}, {"TzHaar Fight Cave", "Fight Cave"},
			{"The Inferno", "Inferno"}, {"Crazy archaeologist", "Crazy Arch"}, {"Bryophyta", "Bryo"},
			{"Cerberus", "Cerb"}, {"Tormented Demon", "TD"}, {"Royal Titans", "Titans"}, {TREASURE_TRAILS, "Clues"}
		};
		for (String[] pair : pairs)
		{
			ABBREVIATIONS.put(normalize(pair[0]), pair[1]);
		}
	}

	/** The wiki's short name for a source (ToB, CoX, KBD...), or the source itself if it has none. */
	static String abbreviation(String source)
	{
		String abbreviation = ABBREVIATIONS.get(normalize(source));
		return abbreviation != null ? abbreviation : source;
	}

	static List<String> lookup(String source)
	{
		List<String> table = TABLES.get(normalize(source));
		return table == null ? null : Collections.unmodifiableList(table);
	}

	/** Lowercase, drop parentheticals like "(uncharged)" and punctuation, collapse whitespace. */
	static String normalize(String s)
	{
		return s.replace(' ', ' ')
			.toLowerCase()
			.replaceAll("\\(.*?\\)", " ")
			.replaceAll("[-_]", " ")
			.replaceAll("[^a-z0-9 ]", "")
			.replaceAll("\\s+", " ")
			.trim();
	}

	/** Matches loose input like "dex scroll" to "Dexterous prayer scroll" in the table; else returns input. */
	static String matchItem(String input, List<String> table)
	{
		if (table == null)
		{
			return input;
		}
		String wanted = normalize(input);
		for (String item : table)
		{
			if (normalize(item).equals(wanted))
			{
				return item;
			}
		}
		String[] wantedWords = wanted.split(" ");
		for (String item : table)
		{
			String[] itemWords = normalize(item).split(" ");
			boolean all = true;
			for (String w : wantedWords)
			{
				boolean found = false;
				for (String iw : itemWords)
				{
					if (iw.startsWith(w))
					{
						found = true;
						break;
					}
				}
				if (!found)
				{
					all = false;
					break;
				}
			}
			if (all)
			{
				return item;
			}
		}
		return input;
	}

	/** Item name for the market title, without suffixes like "(uncharged)". */
	static String displayName(String item)
	{
		return item.replaceAll("\\s*\\(.*?\\)", "").trim();
	}

	/**
	 * Parses "Source: Item" lines into normalized canonical source -> items, so "CoX: Dex scroll" works.
	 * Multiple lines for the same source are all kept (not overwritten), so the caller can roll between
	 * them - each line is an equally-weighted entry, so repeating one gives it more weight.
	 */
	static Map<String, List<String>> parsePriorities(String config)
	{
		Map<String, List<String>> out = new HashMap<>();
		if (config == null)
		{
			return out;
		}
		for (String line : config.split("\\r?\\n"))
		{
			int sep = indexOfSeparator(line);
			if (sep <= 0)
			{
				continue;
			}
			String source = line.substring(0, sep).trim();
			String item = line.substring(sep + 1).trim();
			if (!source.isEmpty() && !item.isEmpty())
			{
				out.computeIfAbsent(normalize(canonicalSource(source)), k -> new ArrayList<>()).add(item);
			}
		}
		return out;
	}

	private static int indexOfSeparator(String line)
	{
		int colon = line.indexOf(':');
		int equals = line.indexOf('=');
		if (colon < 0)
		{
			return equals;
		}
		return equals < 0 ? colon : Math.min(colon, equals);
	}
}

package com.dropmarket;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Keeps a bug on our side from ever reaching the game client. Everything RuneLite calls into (events, the overlay,
 * start and stop) runs through here: a failure is logged once per place and swallowed, and the plugin carries on.
 */
@Slf4j
@Singleton
class Guard
{
	private final Set<String> reported = ConcurrentHashMap.newKeySet();
	private final AtomicInteger failures = new AtomicInteger();

	@Inject
	Guard()
	{
	}

	void run(String where, Runnable action)
	{
		try
		{
			action.run();
		}
		catch (Exception | LinkageError | StackOverflowError e)
		{
			report(where, e);
		}
	}

	<T> T call(String where, Supplier<T> action, T fallback)
	{
		try
		{
			return action.get();
		}
		catch (Exception | LinkageError | StackOverflowError e)
		{
			report(where, e);
			return fallback;
		}
	}

	/** How many failures have been swallowed so far; the integration tests expect this to stay at 0. */
	int failures()
	{
		return failures.get();
	}

	/** The places that have failed, for test output. */
	Set<String> failedPlaces()
	{
		return reported;
	}

	// A broken overlay would fail 50 times a second, so each place is only logged the first time.
	private void report(String where, Throwable e)
	{
		failures.incrementAndGet();
		if (reported.add(where))
		{
			log.warn("Prediction Market Drops hit a problem in {} and kept going", where, e);
		}
	}
}

package com.dropmarket;

import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

/**
 * The only way the plugin talks to RuneLite's item and price data. It never throws and never hands back null: an
 * unknown item has an empty name, a failed search is an empty list and a failed price is 0.
 */
@Slf4j
@Singleton
class ItemLookup
{
	private final ItemManager itemManager;

	@Inject
	ItemLookup(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/** The item's name, or an empty string if the game has no such item (or isn't ready). */
	String nameOf(int id)
	{
		try
		{
			ItemComposition composition = itemManager.getItemComposition(id);
			String name = composition == null ? null : composition.getName();
			return name == null ? "" : name;
		}
		catch (Exception e)
		{
			log.debug("Item lookup failed for {}", id, e);
			return "";
		}
	}

	/** The name of an item's canonical form (a noted or placeholder item resolves to the real one). */
	String canonicalNameOf(int id)
	{
		try
		{
			return nameOf(itemManager.canonicalize(id));
		}
		catch (Exception e)
		{
			log.debug("Item canonicalize failed for {}", id, e);
			return nameOf(id);
		}
	}

	/** Grand Exchange search results; empty until prices have loaded. */
	List<ItemPrice> search(String name)
	{
		try
		{
			List<ItemPrice> results = itemManager.search(name);
			return results == null ? Collections.emptyList() : results;
		}
		catch (Exception e)
		{
			log.debug("Item search failed for {}", name, e);
			return Collections.emptyList();
		}
	}

	long priceOf(int id)
	{
		try
		{
			return itemManager.getItemPrice(id);
		}
		catch (Exception e)
		{
			log.debug("Item price failed for {}", id, e);
			return 0;
		}
	}
}

package com.dropmarket;

import java.util.Random;

class MarketGraph
{
	static final int POINTS = 40;
	/** The plugin steps a live graph every 5 game ticks (3 seconds); profile timing below is counted in those steps. */
	static final int STEP_SECONDS = 3;
	private static final double MIN = 1;
	// Below LOW_MARK for several steps in a row the line is nudged back up; above HIGH_MARK it is pulled back down.
	private static final double LOW_MARK = 9;
	private static final double HIGH_MARK = 74;
	private static final int LOW_DWELL_STEPS = 6;
	private static final int HIGH_DWELL_STEPS = 6;
	// A drift profile lasts 10-15 minutes of live stepping, whatever the player is doing; after that it eases into the
	// next one at the next finished kill or action.
	private static final int PROFILE_MIN_STEPS = 10 * 60 / STEP_SECONDS;
	private static final int PROFILE_EXTRA_STEPS = 5 * 60 / STEP_SECONDS;
	private static final int TRANSITION_STEPS = 20;

	private final Random random;
	private final double[] points = new double[POINTS];
	private int head;
	private int count;
	private double anchor;
	private long volume;

	private DriftProfile profile;
	private int profileStepsLeft;
	private boolean switchPending;
	// While easing into a new profile the anchor glides to this goal instead of jumping.
	private double anchorGoal;
	private int transitionLeft;
	// Per-step anchor change (CLIMBER up, FADER down) and where the climb ends.
	private double trend;
	private double climbTarget;
	private int spikeLeft;
	private double spikeBase;
	private int lowDwell;
	private int highDwell;
	private int liftSteps;

	MarketGraph(Random random)
	{
		this.random = random;
	}

	DriftProfile profile()
	{
		return profile;
	}

	/**
	 * Opens a fresh market with a believable-looking price history already on the chart. The drift profile is NOT
	 * re-rolled here: it runs on its own clock and carries over when the player switches boss, raid or skill.
	 */
	void reset()
	{
		if (profile == null)
		{
			beginProfile(DriftProfile.roll(random), false);
		}
		rebuildHistory();
	}

	/** Starts over with a specific profile (and a fresh clock); used by tests. */
	void reset(DriftProfile forced)
	{
		beginProfile(forced, false);
		rebuildHistory();
	}

	private void rebuildHistory()
	{
		head = 0;
		count = 0;
		lowDwell = 0;
		highDwell = 0;
		liftSteps = 0;
		volume = 50_000L + (long) (random.nextDouble() * 5_000_000L);
		push(clamp(anchor + random.nextGaussian() * 6, anchor));
		for (int i = 1; i < POINTS; i++)
		{
			step(false);
		}
	}

	/** Switches to a profile. Graceful switches glide the anchor over to the new profile's level. */
	private void beginProfile(DriftProfile next, boolean graceful)
	{
		profile = next;
		profileStepsLeft = PROFILE_MIN_STEPS + random.nextInt(PROFILE_EXTRA_STEPS + 1);
		switchPending = false;
		trend = 0;
		spikeLeft = 0;
		if (profile == DriftProfile.CLIMBER)
		{
			trend = 0.45 + random.nextDouble() * 0.35;
			climbTarget = 84 + random.nextDouble() * 6;
		}
		else if (profile == DriftProfile.FADER)
		{
			trend = -(0.25 + random.nextDouble() * 0.15);
		}
		double start = profile.rollAnchor(random);
		if (graceful)
		{
			anchorGoal = start;
			transitionLeft = TRANSITION_STEPS;
		}
		else
		{
			anchor = start;
			transitionLeft = 0;
		}
	}

	void step()
	{
		step(true);
	}

	/** A live step also runs the profile clock and its dynamics; history prefill steps only wander. */
	private void step(boolean live)
	{
		double last = current();
		if (live)
		{
			if (profileStepsLeft > 0 && --profileStepsLeft == 0)
			{
				// The clock has run out, but the switch waits for the current kill or action to finish.
				switchPending = true;
			}
			advanceProfile();
		}
		double drift = (anchor - last) * 0.08;
		double move = random.nextGaussian() * profile.noise;
		if (liftSteps > 0)
		{
			// Climbing out of a low patch: a steady push on top of the anchor pull.
			move += 2.5;
			liftSteps--;
		}
		if (profile.jumpChance > 0 && random.nextDouble() < profile.jumpChance)
		{
			move += (random.nextBoolean() ? 1 : -1) * (profile.jumpMin + random.nextDouble() * profile.jumpSpan);
		}
		double next = clamp(last + drift + move, last);
		trackDwell(next);
		push(next);
		volume += (long) (random.nextDouble() * 180_000L);
		if (live && profile.rerollChance > 0 && random.nextDouble() < profile.rerollChance)
		{
			anchor = profile.rollAnchor(random);
		}
	}

	/**
	 * Call when one unit of the activity finishes (a kill, a loot, a skilling action). If the profile's 10-15 minutes
	 * are up, this is the moment it eases into the next one, so a profile never changes mid-attempt.
	 */
	void completeActivity()
	{
		if (switchPending)
		{
			beginProfile(nextProfile(), true);
		}
	}

	/** True once a profile's time is up and it is only waiting for the next finished kill or action. */
	boolean switchPending()
	{
		return switchPending;
	}

	/** A different profile from the current one, by the usual odds. */
	private DriftProfile nextProfile()
	{
		DriftProfile next = DriftProfile.roll(random);
		for (int tries = 0; next == profile && tries < 8; tries++)
		{
			next = DriftProfile.roll(random);
		}
		return next;
	}

	/** Moves the anchor the line is pulled toward, for the profiles that change over time. */
	private void advanceProfile()
	{
		if (transitionLeft > 0)
		{
			anchor += (anchorGoal - anchor) / transitionLeft;
			transitionLeft--;
			return;
		}
		switch (profile)
		{
			case CLIMBER:
				anchor += trend;
				if (anchor >= climbTarget)
				{
					// The fight is over: settle back to everyday movement from a mid level.
					profile = DriftProfile.STEADY;
					anchor = 28 + random.nextDouble() * 20;
				}
				break;
			case FADER:
				anchor += trend;
				if (anchor <= 16)
				{
					profile = DriftProfile.STEADY;
					anchor = profile.rollAnchor(random);
				}
				break;
			case SPIKE:
				if (spikeLeft > 0)
				{
					spikeLeft--;
					if (spikeLeft == 0)
					{
						anchor = spikeBase;
					}
				}
				else if (random.nextDouble() < 0.03)
				{
					spikeLeft = 6 + random.nextInt(5);
					spikeBase = anchor;
					anchor = Math.min(anchor + 25 + random.nextDouble() * 10, 70);
				}
				break;
			default:
				break;
		}
	}

	/** Keeps the line from sitting very low, or very high, for long. */
	private void trackDwell(double value)
	{
		lowDwell = value < LOW_MARK ? lowDwell + 1 : 0;
		if (lowDwell >= LOW_DWELL_STEPS)
		{
			anchor = Math.max(anchor, 18 + random.nextDouble() * 22);
			liftSteps = 6;
			lowDwell = 0;
		}
		highDwell = value > HIGH_MARK && profile != DriftProfile.CLIMBER ? highDwell + 1 : 0;
		if (highDwell >= HIGH_DWELL_STEPS)
		{
			anchor = Math.min(anchor, 30 + random.nextDouble() * 15);
			highDwell = 0;
		}
	}

	void addVolume(long amount)
	{
		volume += amount;
	}

	void pinToCertain()
	{
		push(100);
		volume += 25_000_000L + (long) (random.nextDouble() * 50_000_000L);
	}

	private void push(double value)
	{
		points[head] = value;
		head = (head + 1) % POINTS;
		count = Math.min(count + 1, POINTS);
	}

	/** Inside the profile's ceiling, but never snapping down: a line already above it (end of a climb) just can't rise. */
	private double clamp(double v, double last)
	{
		double upper = Math.max(profile.ceiling, last);
		return Math.max(MIN, Math.min(upper, v));
	}

	int size()
	{
		return count;
	}

	/** Oldest-first access: get(0) is the oldest point, get(size() - 1) the newest. */
	double get(int i)
	{
		int start = (head - count + POINTS) % POINTS;
		return points[(start + i) % POINTS];
	}

	double current()
	{
		return count == 0 ? 0 : get(count - 1);
	}

	double previous()
	{
		return count < 2 ? current() : get(count - 2);
	}

	long volume()
	{
		return volume;
	}
}

package com.dropmarket;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import java.util.function.ToIntFunction;

final class MarketPainter
{
	static final Color RAID_PURPLE = new Color(0xEF20FF);

	private static final Color BACKGROUND = new Color(12, 14, 18, 200);
	private static final Color BORDER = new Color(255, 255, 255, 30);
	private static final Color GRID = new Color(255, 255, 255, 45);
	private static final Color MUTED = new Color(150, 156, 166);
	private static final Color TITLE = new Color(235, 237, 240);
	private static final Color LIVE_RED = new Color(0xFF3B5C);
	private static final Color EYE = new Color(20, 20, 24);
	private static final Font BAR_TEXT_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 10);
	private static final Stroke GRID_STROKE = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER,
		10f, new float[]{2f, 3f}, 0f);
	private static final Stroke LINE_STROKE = new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final int PAD = 6;
	// All animation here steps once per game tick (0.6s) rather than wall-clock time, so it stays in lockstep
	// with everything else OSRS does on the tick.
	private static final int FLASH_PERIOD_TICKS = 2;
	private static final int DOT_PERIOD_TICKS = 1;
	private static final int PULSE_PERIOD_TICKS = 3;
	private static final int BRAND_BAR_H = 14;
	private static final int COMPACT_BODY_H = 56;
	private static final int TICKER_H = 20;
	// Spacing in the odds row: big number to its change, between the two numbers, and between two changes.
	private static final int CHANGE_GAP = 7;
	private static final int GROUP_GAP = 14;
	private static final int PAIR_GAP = 10;
	private static final int SCROLL_GAP = 28;
	private static final int SCROLL_PX_PER_TICK = 8;

	private MarketPainter()
	{
	}

	static void paint(Graphics2D graphics, int w, int h, String title, MarketGraph graph, MarketGraph polyGraph,
		DropMarketConfig config, boolean resolved, long nowTick, Font titleFont, Font smallFont, String badge,
		boolean badgeSkull, long volumePop, int delta1, int delta2)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			boolean flashOn = resolved && config.flashOnWin() && (nowTick / FLASH_PERIOD_TICKS) % 2 == 0;
			Color lineColor = config.line1Color();
			Color accent = flashOn ? RAID_PURPLE : lineColor;
			MarketGraph secondLine = config.showSecondLine() ? polyGraph : null;
			Color accent2 = flashOn ? RAID_PURPLE : config.line2Color();

			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			RoundRectangle2D panel = new RoundRectangle2D.Double(0, 0, w - 1, h - 1, 8, 8);
			g.setColor(BACKGROUND);
			g.fill(panel);
			if (flashOn)
			{
				g.setColor(new Color(RAID_PURPLE.getRed(), RAID_PURPLE.getGreen(), RAID_PURPLE.getBlue(), 45));
				g.fill(panel);
			}

			OverlayLayout layout = config.overlayLayout();
			boolean bars = layout != OverlayLayout.TICKER;
			int y = 0;
			if (bars && config.showBar1())
			{
				g.setColor(config.bar1Color());
				g.fillRect(0, y, w, BRAND_BAR_H);
				if (config.bar1Text() != null && !config.bar1Text().isEmpty())
				{
					drawBarText(g, config.bar1Text(), w, y, BRAND_BAR_H, config.bar1TextColor());
				}
				y += BRAND_BAR_H;
			}
			if (bars && config.showBar2())
			{
				g.setColor(config.bar2Color());
				g.fillRect(0, y, w, BRAND_BAR_H);
				if (config.bar2Text() != null && !config.bar2Text().isEmpty())
				{
					drawBarText(g, config.bar2Text(), w, y, BRAND_BAR_H, config.bar2TextColor());
				}
				y += BRAND_BAR_H;
			}

			g.setColor(flashOn ? RAID_PURPLE : BORDER);
			g.setStroke(new BasicStroke(flashOn ? 2f : 1f));
			g.draw(panel);

			if (layout == OverlayLayout.COMPACT)
			{
				paintCompact(g, w, y, title, graph, secondLine, accent, accent2, config, nowTick, titleFont, smallFont,
					badge, delta1, delta2);
				return;
			}
			if (layout == OverlayLayout.TICKER)
			{
				paintTicker(g, w, h, title, graph, secondLine, accent, accent2, config, nowTick, titleFont, smallFont,
					delta1, delta2);
				return;
			}

			Font bigFont = titleFont.deriveFont(titleFont.getSize2D() * 1.25f);
			FontMetrics titleFm = g.getFontMetrics(titleFont);
			FontMetrics smallFm = g.getFontMetrics(smallFont);
			FontMetrics bigFm = g.getFontMetrics(bigFont);

			y += PAD;
			int liveBaseline = y + smallFm.getAscent();
			int lx = PAD;
			boolean dotOn = (nowTick / DOT_PERIOD_TICKS) % 2 == 0;
			int dotR = 3;
			g.setFont(smallFont.deriveFont(Font.BOLD));
			FontMetrics liveFm = g.getFontMetrics();
			double dotCenterY = liveBaseline - liveFm.getAscent() / 2.0 - 1;
			g.setColor(dotOn ? LIVE_RED : withAlpha(LIVE_RED, 80));
			g.fill(new Ellipse2D.Double(lx, dotCenterY - dotR, dotR * 2, dotR * 2));
			lx += dotR * 2 + 4;
			text(g, "LIVE", lx, liveBaseline, LIVE_RED);
			lx += liveFm.stringWidth("LIVE") + 8;

			int skullSize = Math.max(6, smallFm.getAscent() - 2);
			if (badge != null && !badge.isEmpty())
			{
				g.setFont(smallFont);
				lx += 2;
				text(g, "·", lx, liveBaseline, MUTED);
				lx += smallFm.stringWidth("·") + 6;
				if (badgeSkull)
				{
					drawSkull(g, lx, (int) Math.round(dotCenterY + skullSize / 2.0), skullSize, MUTED);
					lx += skullSize + 3;
				}
				text(g, badge, lx, liveBaseline, MUTED);
			}
			y += Math.max(smallFm.getHeight(), skullSize + 2) + 4;

			List<String> lines = wrap(title.toUpperCase(), titleFm, w - PAD * 2, 2);
			g.setFont(titleFont);
			for (String line : lines)
			{
				y += titleFm.getAscent();
				text(g, line, PAD, y, TITLE);
				y += titleFm.getDescent();
			}

			y += 3 + bigFm.getAscent();
			int pct = (int) Math.round(graph.current());
			String pctText = pct + "%";
			String pct2 = secondLine == null ? null : Math.round(secondLine.current()) + "%";
			drawOdds(g, PAD, y, w - PAD, true, bigFont, smallFont, accent, accent2, pctText, pct2, delta1, delta2, config);
			y += bigFm.getDescent();
			g.setFont(smallFont);

			int footerH = smallFm.getAscent() + 2;
			int labelW = smallFm.stringWidth("100%") + 4;
			int chartLeft = PAD;
			int chartRight = w - PAD - labelW;
			int chartTop = y + 4 + smallFm.getAscent() / 2;
			int chartBottom = h - PAD - footerH - smallFm.getAscent() / 2;
			if (chartBottom - chartTop >= 10 && chartRight - chartLeft >= 20)
			{
				drawChart(g, graph, secondLine, accent, accent2, chartLeft, chartTop, chartRight,
					chartBottom, smallFm, nowTick);
			}

			int footY = h - PAD;
			g.setFont(smallFont);
			String volume = formatVolume(graph.volume());
			text(g, volume, PAD, footY, MUTED);
			int footRight = w - PAD;
			if (resolved)
			{
				String badgeText = "RESOLVED: YES";
				footRight -= smallFm.stringWidth(badgeText);
				text(g, badgeText, footRight, footY, flashOn ? RAID_PURPLE : TITLE);
			}
			if (volumePop > 0)
			{
				String pop = "+ " + formatPop(volumePop);
				int px = PAD + smallFm.stringWidth(volume) + 6;
				if (px + smallFm.stringWidth(pop) <= footRight - 4)
				{
					text(g, pop, px, footY, accent);
				}
			}
		}
		finally
		{
			g.dispose();
		}
	}

	/** Height of the overlay for a layout; Full keeps whatever size the player resized it to (returns -1). */
	static int layoutHeight(DropMarketConfig config)
	{
		switch (config.overlayLayout())
		{
			case COMPACT:
				return (config.showBar1() ? BRAND_BAR_H : 0) + (config.showBar2() ? BRAND_BAR_H : 0) + COMPACT_BODY_H;
			case TICKER:
				return TICKER_H;
			default:
				return -1;
		}
	}

	/** Two rows: live dot + title (+ badge), then the odds with their changes and a sparkline. */
	private static void paintCompact(Graphics2D g, int w, int top, String title, MarketGraph graph,
		MarketGraph secondLine, Color accent, Color accent2, DropMarketConfig config, long nowTick, Font titleFont,
		Font smallFont, String badge, int delta1, int delta2)
	{
		FontMetrics titleFm = g.getFontMetrics(titleFont);
		FontMetrics smallFm = g.getFontMetrics(smallFont);
		Font bigFont = titleFont.deriveFont(titleFont.getSize2D() * 1.25f);
		FontMetrics bigFm = g.getFontMetrics(bigFont);

		int y = top + PAD;
		int baseline = y + titleFm.getAscent();
		int x = PAD;
		int dotR = 3;
		boolean dotOn = (nowTick / DOT_PERIOD_TICKS) % 2 == 0;
		g.setColor(dotOn ? LIVE_RED : withAlpha(LIVE_RED, 80));
		g.fill(new Ellipse2D.Double(x, baseline - titleFm.getAscent() / 2.0 - dotR - 1, dotR * 2, dotR * 2));
		x += dotR * 2 + 5;

		int right = w - PAD;
		if (badge != null && !badge.isEmpty())
		{
			g.setFont(smallFont);
			right -= smallFm.stringWidth(badge);
			text(g, badge, right, baseline, MUTED);
			right -= 6;
		}
		g.setFont(titleFont);
		text(g, compactTitle(title, titleFm::stringWidth, right - x), x, baseline, TITLE);
		y += titleFm.getHeight() + 2;

		int pctBaseline = y + bigFm.getAscent();
		String pctText = Math.round(graph.current()) + "%";
		g.setFont(bigFont);
		String pct2 = secondLine == null ? null : Math.round(secondLine.current()) + "%";
		// The numbers sit 2px lower than the row they were laid out on; the sparkline keeps its place.
		int dx = drawOdds(g, PAD, pctBaseline + 3, w - PAD - 24, false, bigFont, smallFont, accent, accent2, pctText, pct2, delta1,
			delta2, config);

		int sparkLeft = dx + 12;
		int sparkRight = w - PAD - 3;
		if (sparkRight - sparkLeft >= 24)
		{
			int sparkTop = y + 2;
			int sparkBottom = pctBaseline + bigFm.getDescent() - 2;
			if (secondLine != null)
			{
				drawLine(g, secondLine, accent2, sparkLeft, sparkTop, sparkRight, sparkBottom, nowTick);
			}
			drawLine(g, graph, accent, sparkLeft, sparkTop, sparkRight, sparkBottom, nowTick);
		}
	}

	/** One line: live dot, title, odds, change(s) and a small sparkline, like a stock ticker. */
	private static void paintTicker(Graphics2D g, int w, int h, String title, MarketGraph graph,
		MarketGraph secondLine, Color accent, Color accent2, DropMarketConfig config, long nowTick, Font titleFont,
		Font smallFont, int delta1, int delta2)
	{
		FontMetrics titleFm = g.getFontMetrics(titleFont);
		int baseline = (h + titleFm.getAscent() - titleFm.getDescent()) / 2;

		int dotR = 3;
		boolean dotOn = (nowTick / DOT_PERIOD_TICKS) % 2 == 0;
		g.setColor(dotOn ? LIVE_RED : withAlpha(LIVE_RED, 80));
		g.fill(new Ellipse2D.Double(PAD, h / 2.0 - dotR, dotR * 2, dotR * 2));
		int titleLeft = PAD + dotR * 2 + 5;

		int right = w - PAD;
		int sparkW = w >= 260 ? 44 : 0;
		// Only wide strips have room for the second line's change next to the odds.
		boolean secondDelta = secondLine != null && w >= 300;
		if (sparkW > 0)
		{
			int sparkLeft = right - sparkW;
			if (secondLine != null)
			{
				drawLine(g, secondLine, accent2, sparkLeft, 4, right - 3, h - 4, nowTick);
			}
			drawLine(g, graph, accent, sparkLeft, 4, right - 3, h - 4, nowTick);
			right = sparkLeft - 8;
		}

		boolean secondNumber = secondLine != null && config.showSecondNumber() && w >= 300;
		String pct1 = Math.round(graph.current()) + "%";
		String pct2 = secondLine == null ? "" : Math.round(secondLine.current()) + "%";
		int d1W = deltaWidth(g, delta1, smallFont);
		int d2W = secondLine == null ? 0 : deltaWidth(g, delta2, smallFont);
		int groupGap = 10;
		int group1W = titleFm.stringWidth(pct1) + 6 + d1W;
		int group2W = secondNumber ? titleFm.stringWidth(pct2) + 6 + d2W : secondDelta ? d2W : 0;
		int startX = right - (group1W + (group2W > 0 ? groupGap + group2W : 0));
		int x = startX;
		g.setFont(titleFont);
		text(g, pct1, x, baseline, accent);
		x += titleFm.stringWidth(pct1) + 6;
		x += drawDelta(g, x, baseline, delta1, accent, config.line1FallingColor(), smallFont);
		if (group2W > 0)
		{
			x += groupGap;
			if (secondNumber)
			{
				g.setFont(titleFont);
				text(g, pct2, x, baseline, accent2);
				x += titleFm.stringWidth(pct2) + 6;
			}
			drawDelta(g, x, baseline, delta2, accent2, config.line2FallingColor(), smallFont);
		}
		Font tickerTitleFont = smallFont.deriveFont(Font.BOLD);
		g.setFont(tickerTitleFont);
		FontMetrics tickerFm = g.getFontMetrics(tickerTitleFont);
		int titleRight = startX - 8;
		String shortTitle = abbreviatedTitle(title);
		if (tickerFm.stringWidth(shortTitle) <= titleRight - titleLeft)
		{
			text(g, shortTitle, titleLeft, baseline, TITLE);
		}
		else
		{
			scrollText(g, shortTitle, tickerFm, titleLeft, titleRight, baseline, nowTick);
		}
	}

	/**
	 * The title for the compact layouts: "THEATRE OF BLOOD DROPS SCYTHE OF VITUR" becomes "TOB DROPS SCYTHE OF VITUR"
	 * (the wiki's short name), then "DROPS SCYTHE OF VITUR", then "DROPS SCYTHE" if the room runs out.
	 */
	static String compactTitle(String title, ToIntFunction<String> width, int maxWidth)
	{
		String upper = title.toUpperCase();
		String verb = upper.contains(" DROPS ") ? " DROPS " : upper.contains(" GETS ") ? " GETS " : null;
		if (verb == null)
		{
			return fit(upper, width, maxWidth);
		}
		int at = upper.indexOf(verb);
		String item = upper.substring(at + verb.length());
		String source = DropTables.abbreviation(title.substring(0, at)).toUpperCase();
		String verbWord = verb.trim();
		String firstWord = item.split(" ")[0];
		for (String candidate : new String[]{source + verb + item, verbWord + " " + item, verbWord + " " + firstWord})
		{
			if (width.applyAsInt(candidate) <= maxWidth)
			{
				return candidate;
			}
		}
		return fit(verbWord + " " + firstWord, width, maxWidth);
	}

	/** Source swapped for its wiki short name (ToB, CoX...), everything else untouched, upper-cased. */
	static String abbreviatedTitle(String title)
	{
		String upper = title.toUpperCase();
		String verb = upper.contains(" DROPS ") ? " DROPS " : upper.contains(" GETS ") ? " GETS " : null;
		if (verb == null)
		{
			return upper;
		}
		int at = upper.indexOf(verb);
		return DropTables.abbreviation(title.substring(0, at)).toUpperCase() + upper.substring(at);
	}

	/** Scrolls text right to left inside [left, right], looping like a stock ticker; one step per game tick. */
	private static void scrollText(Graphics2D g, String s, FontMetrics fm, int left, int right, int baseline,
		long nowTick)
	{
		int cycle = fm.stringWidth(s) + SCROLL_GAP;
		int offset = (int) ((nowTick * SCROLL_PX_PER_TICK) % cycle);
		java.awt.Shape oldClip = g.getClip();
		g.clipRect(left, 0, right - left, baseline + fm.getDescent() + 4);
		text(g, s, left - offset, baseline, TITLE);
		text(g, s, left - offset + cycle, baseline, TITLE);
		g.setClip(oldClip);
	}

	private static String fit(String s, ToIntFunction<String> width, int maxWidth)
	{
		String out = s;
		while (out.length() > 1 && width.applyAsInt(out) > maxWidth)
		{
			out = out.substring(0, out.length() - 1);
		}
		return out.length() < s.length() ? out.trim() + "..." : out;
	}

	private static int deltaWidth(Graphics2D g, int delta, Font smallFont)
	{
		FontMetrics fm = g.getFontMetrics(deltaFont(smallFont));
		return (delta != 0 ? 11 : 0) + fm.stringWidth(Math.abs(delta) + "%");
	}

	/**
	 * Draws line 1's big number and change on the left, then line 2. With the second number on, line 2's number and
	 * change sit at the right edge of the box (Full) or follow line 1's (Compact, which keeps the right for its
	 * sparkline). Without the second number, line 2's change just follows line 1's. Returns where the row ended.
	 */
	private static int drawOdds(Graphics2D g, int startX, int baseline, int limit, boolean full, Font bigFont,
		Font smallFont, Color accent, Color accent2, String pct1, String pct2, int delta1, int delta2,
		DropMarketConfig config)
	{
		FontMetrics bigFm = g.getFontMetrics(bigFont);
		int pct1W = bigFm.stringWidth(pct1);
		int d1W = deltaWidth(g, delta1, smallFont);
		int d2W = pct2 == null ? 0 : deltaWidth(g, delta2, smallFont);
		int pct2W = pct2 == null ? 0 : bigFm.stringWidth(pct2);
		boolean number = pct2 != null && config.showSecondNumber();
		int needed = 0;
		if (number)
		{
			needed = pct1W + CHANGE_GAP + d1W + GROUP_GAP + pct2W + CHANGE_GAP + d2W;
			number = startX + needed <= limit;
		}

		if (number)
		{
			int x = startX;
			g.setFont(bigFont);
			text(g, pct1, x, baseline, accent);
			x += pct1W + CHANGE_GAP;
			x += drawDelta(g, x, baseline, delta1, accent, config.line1FallingColor(), smallFont);
			// Line 2's readout hugs the right edge in Full; Compact keeps that side for its sparkline.
			x = full ? limit - (pct2W + CHANGE_GAP + d2W) : x + GROUP_GAP;
			g.setFont(bigFont);
			text(g, pct2, x, baseline, accent2);
			x += pct2W + CHANGE_GAP;
			return x + drawDelta(g, x, baseline, delta2, accent2, config.line2FallingColor(), smallFont);
		}

		int x = startX;
		g.setFont(bigFont);
		text(g, pct1, x, baseline, accent);
		x += pct1W + CHANGE_GAP;
		x += drawDelta(g, x, baseline, delta1, accent, config.line1FallingColor(), smallFont);
		if (pct2 == null)
		{
			return x;
		}
		// No second number: line 2's change simply follows line 1's.
		x += PAIR_GAP;
		return x + drawDelta(g, x, baseline, delta2, accent2, config.line2FallingColor(), smallFont);
	}

	/** Always renders (the delta should never disappear); the arrow is skipped only for an exact 0. */
	private static int drawDelta(Graphics2D g, int x, int y, int delta, Color positiveColor, Color negativeColor,
		Font smallFont)
	{
		Color color = delta < 0 ? negativeColor : positiveColor;
		String deltaText = Math.abs(delta) + "%";
		Font deltaFont = deltaFont(smallFont);
		FontMetrics deltaFm = g.getFontMetrics(deltaFont);
		int triW = 7;
		int mid = y - deltaFm.getAscent() / 2 - 1;
		if (delta < 0)
		{
			// Drop the down-triangle back down 1px relative to the up-triangle's nudge.
			mid += 1;
		}
		int textX = x;
		if (delta != 0)
		{
			Polygon tri = delta > 0
				? new Polygon(new int[]{x, x + triW, x + triW / 2}, new int[]{mid + 3, mid + 3, mid - 3}, 3)
				: new Polygon(new int[]{x, x + triW, x + triW / 2}, new int[]{mid - 3, mid - 3, mid + 3}, 3);
			g.setColor(color);
			g.fill(tri);
			textX = x + triW + 4;
		}
		g.setFont(deltaFont);
		text(g, deltaText, textX, y, color);
		return (textX - x) + deltaFm.stringWidth(deltaText);
	}

	private static Font deltaFont(Font smallFont)
	{
		return smallFont.deriveFont(Font.BOLD, smallFont.getSize2D() * 1.15f);
	}

	private static void drawBarText(Graphics2D g, String s, int w, int barTop, int barH, Color color)
	{
		Font old = g.getFont();
		g.setFont(BAR_TEXT_FONT);
		FontMetrics fm = g.getFontMetrics();
		int tx = (w - fm.stringWidth(s)) / 2;
		int ty = barTop + (barH + fm.getAscent() - fm.getDescent()) / 2;
		g.setColor(color);
		g.drawString(s, tx, ty);
		g.setFont(old);
	}

	private static void drawSkull(Graphics2D g, int x, int baselineY, int size, Color color)
	{
		double top = baselineY - size;
		g.setColor(color);
		g.fill(new Ellipse2D.Double(x, top, size, size * 0.78));
		g.fill(new RoundRectangle2D.Double(x + size * 0.22, top + size * 0.58, size * 0.56, size * 0.42, 2, 2));
		g.setColor(EYE);
		double eyeR = size * 0.15;
		double eyeY = top + size * 0.26;
		g.fill(new Ellipse2D.Double(x + size * 0.18, eyeY, eyeR * 2, eyeR * 2));
		g.fill(new Ellipse2D.Double(x + size * 0.82 - eyeR * 2, eyeY, eyeR * 2, eyeR * 2));
		g.fillRect((int) Math.round(x + size * 0.5 - 0.5), (int) Math.round(top + size * 0.78), 1,
			(int) Math.max(1, Math.round(size * 0.2)));
	}

	private static void drawChart(Graphics2D g, MarketGraph graph, MarketGraph secondLine, Color color,
		Color secondColor, int left, int top, int right, int bottom, FontMetrics smallFm, long nowTick)
	{
		g.setStroke(GRID_STROKE);
		int labelGap = smallFm.getAscent() + 1;
		int chartH = bottom - top;
		for (int pct : new int[]{0, 50, 100})
		{
			int gy = yFor(pct, top, bottom);
			g.setColor(GRID);
			g.drawLine(left, gy, right, gy);
			boolean fits = pct == 100 || (pct == 0 ? chartH >= labelGap : chartH / 2 >= labelGap);
			if (fits)
			{
				text(g, pct + "%", right + 4, gy + smallFm.getAscent() / 2 - 1, MUTED);
			}
		}

		if (secondLine != null)
		{
			drawLine(g, secondLine, secondColor, left, top, right, bottom, nowTick);
		}
		drawLine(g, graph, color, left, top, right, bottom, nowTick);
	}

	private static void drawLine(Graphics2D g, MarketGraph graph, Color color, int left, int top, int right,
		int bottom, long nowTick)
	{
		int n = graph.size();
		if (n < 2)
		{
			return;
		}

		Path2D.Double line = new Path2D.Double();
		double lastX = right;
		double lastY = bottom;
		for (int i = 0; i < n; i++)
		{
			double px = left + (double) (right - left) * i / (n - 1);
			double py = top + (bottom - top) * (1 - graph.get(i) / 100.0);
			if (i == 0)
			{
				line.moveTo(px, py);
			}
			else
			{
				line.lineTo(px, py);
			}
			lastX = px;
			lastY = py;
		}

		Path2D.Double area = new Path2D.Double(line);
		area.lineTo(right, bottom);
		area.lineTo(left, bottom);
		area.closePath();
		g.setPaint(new GradientPaint(0, top, withAlpha(color, 70), 0, bottom, withAlpha(color, 0)));
		g.fill(area);

		g.setStroke(LINE_STROKE);
		g.setColor(color);
		g.draw(line);

		double pulse = (nowTick % PULSE_PERIOD_TICKS) / (double) PULSE_PERIOD_TICKS;
		double haloR = 3 + 5 * pulse;
		g.setColor(withAlpha(color, (int) (130 * (1 - pulse))));
		g.fill(new Ellipse2D.Double(lastX - haloR, lastY - haloR, haloR * 2, haloR * 2));
		g.setColor(color);
		g.fill(new Ellipse2D.Double(lastX - 2.5, lastY - 2.5, 5, 5));
	}

	private static int yFor(int pct, int top, int bottom)
	{
		return (int) Math.round(top + (bottom - top) * (1 - pct / 100.0));
	}

	private static void text(Graphics2D g, String s, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(color);
		g.drawString(s, x, y);
	}

	private static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, alpha)));
	}

	static String formatPop(long v)
	{
		if (v >= 1_000_000_000L)
		{
			return String.format("$%.1fB", v / 1e9);
		}
		if (v >= 1_000_000L)
		{
			return String.format("$%.1fM", v / 1e6);
		}
		return String.format("$%dK", v / 1000);
	}

	static String formatVolume(long v)
	{
		if (v >= 1_000_000_000L)
		{
			return String.format("$%.1fB Vol.", v / 1e9);
		}
		if (v >= 1_000_000L)
		{
			return String.format("$%.1fM Vol.", v / 1e6);
		}
		return String.format("$%,dK Vol.", v / 1000);
	}

	static List<String> wrap(String text, FontMetrics fm, int maxWidth, int maxLines)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		String[] words = text.split(" ");
		for (int i = 0; i < words.length; i++)
		{
			String candidate = current.length() == 0 ? words[i] : current + " " + words[i];
			if (fm.stringWidth(candidate) <= maxWidth || current.length() == 0)
			{
				current.setLength(0);
				current.append(candidate);
				continue;
			}
			if (lines.size() == maxLines - 1)
			{
				lines.add(ellipsize(candidate, fm, maxWidth));
				return lines;
			}
			lines.add(current.toString());
			current.setLength(0);
			current.append(words[i]);
		}
		if (current.length() > 0)
		{
			lines.add(lines.size() == maxLines - 1 ? ellipsize(current.toString(), fm, maxWidth) : current.toString());
		}
		return lines;
	}

	private static String ellipsize(String s, FontMetrics fm, int maxWidth)
	{
		if (fm.stringWidth(s) <= maxWidth)
		{
			return s;
		}
		String out = s;
		while (out.length() > 1 && fm.stringWidth(out + "...") > maxWidth)
		{
			out = out.substring(0, out.length() - 1);
		}
		return out.trim() + "...";
	}
}

package com.dropmarket;

import java.util.List;
import java.util.function.Predicate;
import java.util.function.ToLongFunction;

final class MarketPicker
{
	private MarketPicker()
	{
	}

	/** Priciest drop over the threshold, else first locked untradeable slot (pet-first: reversed), else null. */
	static String pick(List<String> table, boolean petFirst, long threshold, ToLongFunction<String> price,
		Predicate<String> lockedSlot)
	{
		String bestTradeable = null;
		long bestPrice = 0;
		String chase = null;
		for (String item : table)
		{
			long p = price.applyAsLong(item);
			if (p > bestPrice)
			{
				bestTradeable = item;
				bestPrice = p;
			}
			else if (p < 0 && chase == null && lockedSlot.test(item))
			{
				chase = item;
			}
		}

		boolean valuable = bestTradeable != null && bestPrice >= threshold;
		if (petFirst)
		{
			return chase != null ? chase : valuable ? bestTradeable : null;
		}
		return valuable ? bestTradeable : chase;
	}
}

package com.dropmarket;

import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Saves {@link OwnedParts} per RuneScape profile, the same way the collection log tracker keeps its data. */
@Singleton
class MultipartTracker
{
	private static final String KEY = "multipartOwned";

	private final ProfileStore store;
	private final OwnedParts parts = new OwnedParts();

	@Inject
	MultipartTracker(ProfileStore store)
	{
		this.store = store;
	}

	void load()
	{
		String value = store.get(KEY);
		parts.replaceAll(value == null || value.isEmpty() ? List.<String>of() : Arrays.asList(value.split(",")));
	}

	boolean owns(String part)
	{
		return parts.owns(part);
	}

	int missing(Collection<String> setParts)
	{
		return parts.missing(setParts);
	}

	/** Returns true if the part was newly recorded (so the caller knows the market may need repicking). */
	boolean add(String part, Collection<String> setParts)
	{
		boolean already = parts.owns(part);
		parts.add(part, setParts);
		if (!already)
		{
			store.set(KEY, String.join(",", parts.snapshot()));
		}
		return !already;
	}
}

