	@Test
	public void compactTitleUsesWikiAbbreviationsThenDropsTheSource()
	{
		// One unit per character keeps the widths easy to reason about.
		java.util.function.ToIntFunction<String> chars = String::length;
		String full = "Theatre of Blood drops Scythe of vitur";
		assertEquals("TOB DROPS SCYTHE OF VITUR", MarketPainter.compactTitle(full, chars, 40));
		assertEquals("DROPS SCYTHE OF VITUR", MarketPainter.compactTitle(full, chars, 24));
		assertEquals("DROPS SCYTHE", MarketPainter.compactTitle(full, chars, 14));
		assertEquals("TOB DROPS TWISTED BOW",
			MarketPainter.compactTitle("Chambers of Xeric drops Twisted bow", chars, 40).replace("COX", "TOB"));
		assertEquals("COX DROPS TWISTED BOW", MarketPainter.compactTitle("Chambers of Xeric drops Twisted bow", chars, 40));
		assertEquals("ZULRAH DROPS TANZANITE FANG", MarketPainter.compactTitle("Zulrah drops Tanzanite fang", chars, 40));
		assertEquals("KBD DROPS DRAGON PICKAXE", MarketPainter.compactTitle("King Black Dragon drops Dragon pickaxe", chars, 40));
		assertEquals("LIVE ODDS", MarketPainter.compactTitle("LIVE ODDS", chars, 40));
		assertEquals("GETS SCYTHE", MarketPainter.compactTitle("Bob GETS Scythe of vitur", chars, 12));
	}

	@Test
	public void longTickerTitlesScrollEachTick() throws Exception
	{
		TestConfig config = new TestConfig();
		config.layout = OverlayLayout.TICKER;
		int h = MarketPainter.layoutHeight(config);
		BufferedImage first = render("Theatre of Blood drops Scythe of vitur", false, 0, 200, h, config, null, 0);
		BufferedImage later = render("Theatre of Blood drops Scythe of vitur", false, 3, 200, h, config, null, 0);
		assertTrue(differs(first, later));
		assertEquals("TOB DROPS SCYTHE OF VITUR", MarketPainter.abbreviatedTitle("Theatre of Blood drops Scythe of vitur"));
	}

	private static boolean differs(BufferedImage a, BufferedImage b)
	{
		for (int y = 0; y < a.getHeight(); y++)
		{
			for (int x = 0; x < a.getWidth(); x++)
			{
				if (a.getRGB(x, y) != b.getRGB(x, y))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static int colorPixelsAbove(BufferedImage img, Color c, int maxY)
	{
		int n = 0;
		for (int y = 0; y < Math.min(maxY, img.getHeight()); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if ((img.getRGB(x, y) & 0xFFFFFF) == (c.getRGB() & 0xFFFFFF))
				{
					n++;
				}
			}
		}
		return n;
	}

	@Test
	public void secondOddsNumberAddsLineTwoTextNextToTheFirst() throws Exception
	{
		MarketGraph poly = new MarketGraph(new Random(99));
		poly.reset();
		TestConfig config = new TestConfig();
		config.showSecondLine = true;
		BufferedImage off = render("Zulrah drops Tanzanite fang", false, 0, 260, 192, config, poly, 0);
		config.showSecondNumber = true;
		BufferedImage on = render("Zulrah drops Tanzanite fang", false, 0, 260, 192, config, poly, 0);
		// The text rows sit above the chart, so extra line-2 colored pixels up there are the second number.
		assertTrue(colorPixelsAbove(on, DropMarketConfig.DEFAULT_LINE2_COLOR, 70)
			> colorPixelsAbove(off, DropMarketConfig.DEFAULT_LINE2_COLOR, 70));
	}

	private static int rightmostColorX(BufferedImage img, Color c, int maxY)
	{
		int best = -1;
		for (int y = 0; y < Math.min(maxY, img.getHeight()); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if ((img.getRGB(x, y) & 0xFFFFFF) == (c.getRGB() & 0xFFFFFF))
				{
					best = Math.max(best, x);
				}
			}
		}
		return best;
	}

	@Test
	public void secondReadoutSitsAtTheRightEdgeAndMainNumberAtTheLeft() throws Exception
	{
		MarketGraph poly = new MarketGraph(new Random(99));
		poly.reset();
		TestConfig config = new TestConfig();
		config.showSecondLine = true;
		config.showSecondNumber = true;
		BufferedImage img = render("Zulrah drops Tanzanite fang", false, 0, 260, 192, config, poly, 0);
		int line2Right = rightmostColorX(img, DropMarketConfig.DEFAULT_LINE2_COLOR, 70);
		assertTrue("line 2 reaches the right edge: " + line2Right, line2Right >= 260 - 12);
	}
}

package com.dropmarket;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.Arrays;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class MarketPickerTest
{
	private static final long THRESHOLD = 250_000;
	private static final Map<String, Long> PRICES = ImmutableMap.of(
		"Tanzanite fang", 1_500_000L,
		"Magic fang", 1_200_000L,
		"Bronze spear", 30L,
		"Leaf-bladed battleaxe", 120_000L);

	private static long price(String item)
	{
		return PRICES.getOrDefault(item, -1L);
	}

	private static String pick(boolean petFirst, Set<String> locked, String... table)
	{
		return MarketPicker.pick(Arrays.asList(table), petFirst, THRESHOLD, MarketPickerTest::price, locked::contains);
	}

	@Test
	public void valuableTradeableWins()
	{
		assertEquals("Tanzanite fang",
			pick(false, ImmutableSet.of("Pet snakeling"), "Tanzanite fang", "Magic fang", "Pet snakeling"));
	}

	@Test
	public void cheapMonsterWithLockedUntradeableChasesIt()
	{
		assertEquals("Goblin champion scroll",
			pick(false, ImmutableSet.of("Goblin champion scroll"), "Bronze spear", "Goblin champion scroll"));
	}

	@Test
	public void cheapMonsterWithEverythingUnlockedIsLiveOdds()
	{
		assertNull(pick(false, ImmutableSet.of(), "Bronze spear", "Goblin champion scroll"));
		assertNull(pick(false, ImmutableSet.of(), "Leaf-bladed battleaxe"));
	}

	@Test
	public void petFirstPrefersLockedPetThenFallsBack()
	{
		assertEquals("Rock golem", pick(true, ImmutableSet.of("Rock golem"), "Rock golem"));
		assertNull(pick(true, ImmutableSet.of(), "Rock golem"));
		assertEquals("Tanzanite fang", pick(true, ImmutableSet.of(), "Phoenix", "Tanzanite fang"));
	}

	@Test
	public void firstLockedSlotInTableOrderIsChosen()
	{
		assertEquals("Fire cape",
			pick(false, ImmutableSet.of("Fire cape", "Tzrek-jad"), "Fire cape", "Tzrek-jad"));
		assertEquals("Tzrek-jad", pick(false, ImmutableSet.of("Tzrek-jad"), "Fire cape", "Tzrek-jad"));
	}
}

package com.dropmarket;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class OwnedPartsTest
{
	private static final List<String> HALBERD = Arrays.asList("Noxious blade", "Noxious point", "Noxious pommel");

	@Test
	public void ownedPartsCantBeMissingAndTheRestSplitTheValue()
	{
		OwnedParts parts = new OwnedParts();
		assertEquals(3, parts.missing(HALBERD));
		parts.add("Noxious pommel", HALBERD);
		assertTrue(parts.owns("noxious POMMEL"));
		assertEquals(2, parts.missing(HALBERD));
		parts.add("Noxious blade", HALBERD);
		assertEquals(1, parts.missing(HALBERD));
	}

	@Test
	public void completingTheSetStartsItOver()
	{
		OwnedParts parts = new OwnedParts();
		assertFalse(parts.add("Noxious pommel", HALBERD));
		assertFalse(parts.add("Noxious blade", HALBERD));
		assertTrue(parts.add("Noxious point", HALBERD));
		assertFalse(parts.owns("Noxious pommel"));
		assertEquals(3, parts.missing(HALBERD));
	}
}

